create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username ~ '^[A-Za-z0-9_]{3,24}$'),display_name text not null default '',email text not null,legal_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.create_profile_for_user() returns trigger language plpgsql security definer set search_path=public,auth as $$ declare n text; begin n:=coalesce(new.raw_user_meta_data->>'username',''); if n !~ '^[A-Za-z0-9_]{3,24}$' then raise exception 'Invalid username'; end if; insert into public.profiles(id,username,display_name,email) values(new.id,n,coalesce(new.raw_user_meta_data->>'display_name',n),new.email); return new; end $$;
drop trigger if exists on_auth_user_created_arcadestore on auth.users;
create trigger on_auth_user_created_arcadestore after insert on auth.users for each row execute procedure public.create_profile_for_user();
create table if not exists public.feature_flags(key text primary key check(key in ('buyer_selling','admin_publishing','reservations','checkout','payouts','live_payments')),enabled boolean not null,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
insert into public.feature_flags(key,enabled) values('buyer_selling',false),('admin_publishing',true),('reservations',true),('checkout',true),('payouts',false),('live_payments',false) on conflict(key) do nothing;
create table if not exists public.feature_flag_logs(id bigint generated always as identity primary key,key text not null,old_value boolean not null,new_value boolean not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references auth.users(id),game text not null check(game in ('Bloodstrike','Free Fire','Call of Duty')),price bigint not null check(price>0),photo_path text,description text not null default '',status text not null default 'draft' check(status in ('draft','published','reserved','held','sold','hidden','deleted')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create index if not exists listings_browse_idx on public.listings(status,game,price);
create table if not exists public.game_art(game text primary key check(game in ('Bloodstrike','Free Fire','Call of Duty')),photo_path text not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table if not exists public.listing_secrets(listing_id uuid primary key references public.listings(id) on delete cascade,ciphertext text not null,iv text not null,updated_at timestamptz not null default now());
create table if not exists public.reservations(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings(id),buyer_id uuid not null references auth.users(id),status text not null default 'active' check(status in ('active','checkout','removed','expired','completed')),created_at timestamptz not null default now(),expires_at timestamptz not null,order_id uuid);
create unique index if not exists one_active_reservation_per_listing on public.reservations(listing_id) where status in ('active','checkout');
create index if not exists buyer_reservations_idx on public.reservations(buyer_id,status,expires_at);
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references auth.users(id),amount bigint not null check(amount>0),status text not null check(status in ('held','paid','expired','needs_refund','refunded','cancelled')),flw_tx_ref text unique,flw_transaction_id text unique,checkout_url text,hold_until timestamptz,created_at timestamptz not null default now(),paid_at timestamptz,refund_reason text,refunded_at timestamptz);
alter table public.reservations drop constraint if exists reservations_order_id_fkey;
alter table public.reservations add constraint reservations_order_id_fkey foreign key(order_id) references public.orders(id);
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,listing_id uuid not null references public.listings(id),seller_id uuid not null references auth.users(id),game text not null,gross bigint not null,commission bigint not null default 0,net bigint not null,unique(order_id,listing_id));
create table if not exists public.ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),direction text not null check(direction in ('credit','debit')),amount bigint not null check(amount>0),entry_type text not null check(entry_type in ('sale','payout','payout_reversal')),order_id uuid references public.orders(id),payout_id uuid,reference text unique,created_at timestamptz not null default now());
create index if not exists ledger_user_idx on public.ledger(user_id,created_at desc);
create table if not exists public.seller_bank_details(user_id uuid primary key references auth.users(id) on delete cascade,account_number_enc text not null,account_number_iv text not null,bank_code text not null,bank_name text not null,updated_at timestamptz not null default now());
create table if not exists public.payouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),amount bigint not null check(amount>=5000),reference text not null unique,provider_id text,status text not null check(status in ('requested','successful','failed','unknown')),reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.ledger add constraint ledger_payout_id_fkey foreign key(payout_id) references public.payouts(id);
create table if not exists public.auth_attempts(key_hash text primary key,window_started_at timestamptz not null,attempts integer not null default 0);
create or replace function public.is_owner() returns boolean language sql stable as $$ select coalesce(auth.jwt()->'app_metadata'->>'role'='owner',false) $$;
create or replace function public.is_admin_or_owner() returns boolean language sql stable as $$ select coalesce(auth.jwt()->'app_metadata'->>'role' in ('owner','admin'),false) $$;
create or replace function public.can_view_order(p_order uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.orders o where o.id=p_order and (o.buyer_id=auth.uid() or public.is_owner() or public.is_admin_or_owner() and exists(select 1 from public.order_items i where i.order_id=o.id and i.seller_id=auth.uid()))) $$;
create or replace function public.consume_auth_attempt(p_key_hash text,p_max integer default 8,p_window_seconds integer default 900) returns boolean language plpgsql security definer set search_path=public as $$ declare r public.auth_attempts%rowtype; begin insert into public.auth_attempts(key_hash,window_started_at,attempts) values(p_key_hash,now(),1) on conflict(key_hash) do nothing; select * into r from public.auth_attempts where key_hash=p_key_hash for update; if r.window_started_at<now()-make_interval(secs=>p_window_seconds) then update public.auth_attempts set window_started_at=now(),attempts=1 where key_hash=p_key_hash; return true; end if; if r.attempts>=p_max then return false; end if; update public.auth_attempts set attempts=attempts+1 where key_hash=p_key_hash; return true; end $$;
create or replace function public.reserve_listing(p_buyer uuid,p_listing uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare l public.listings%rowtype; rid uuid; begin if not coalesce((select enabled from public.feature_flags where key='reservations'),false) then raise exception 'feature disabled'; end if; select * into l from public.listings where id=p_listing for update; if not found or l.status<>'published' then raise exception 'listing unavailable'; end if; insert into public.reservations(listing_id,buyer_id,status,expires_at) values(l.id,p_buyer,'active',now()+interval '48 hours') returning id into rid; update public.listings set status='reserved',updated_at=now() where id=l.id; return rid; end $$;
create or replace function public.release_reservation(p_buyer uuid,p_reservation uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare r public.reservations%rowtype; begin select * into r from public.reservations where id=p_reservation for update; if not found or r.buyer_id<>p_buyer or r.status<>'active' then return false; end if; update public.reservations set status='removed' where id=r.id; update public.listings set status='published',updated_at=now() where id=r.listing_id and status='reserved'; return true; end $$;
create or replace function public.expire_reservations() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin with expired as (update public.reservations set status='expired' where status='active' and expires_at<=now() returning listing_id) update public.listings l set status='published',updated_at=now() from expired e where l.id=e.listing_id and l.status='reserved' and not exists(select 1 from public.reservations r where r.listing_id=l.id and r.status in ('active','checkout')); get diagnostics n=row_count; return coalesce(n,0); end $$;
create or replace function public.create_cart_order(p_buyer uuid,p_tx_ref text) returns public.orders language plpgsql security definer set search_path=public as $$ declare total bigint; o public.orders%rowtype; r record; fee bigint; begin if not coalesce((select enabled from public.feature_flags where key='checkout'),false) then raise exception 'feature disabled'; end if; perform 1 from public.reservations where buyer_id=p_buyer and status='active' and expires_at>now() for update; select coalesce(sum(l.price),0) into total from public.reservations rs join public.listings l on l.id=rs.listing_id where rs.buyer_id=p_buyer and rs.status='active' and rs.expires_at>now() and l.status='reserved'; if total<=0 then raise exception 'cart empty'; end if; insert into public.orders(buyer_id,amount,status,flw_tx_ref,hold_until) values(p_buyer,total,'held',p_tx_ref,now()+interval '20 minutes') returning * into o; for r in select rs.id reservation_id,l.id listing_id,l.seller_id,l.game,l.price,coalesce(u.raw_app_meta_data->>'role','buyer') seller_role from public.reservations rs join public.listings l on l.id=rs.listing_id join auth.users u on u.id=l.seller_id where rs.buyer_id=p_buyer and rs.status='active' and rs.expires_at>now() and l.status='reserved' for update of l,rs loop fee:=case when r.seller_role='owner' then 0 else round(r.price*.20)::bigint end; insert into public.order_items(order_id,listing_id,seller_id,game,gross,commission,net) values(o.id,r.listing_id,r.seller_id,r.game,r.price,fee,r.price-fee); update public.listings set status='held',updated_at=now() where id=r.listing_id; update public.reservations set status='checkout',order_id=o.id,expires_at=o.hold_until where id=r.reservation_id; end loop; return o; end $$;
create or replace function public.attach_checkout(p_buyer uuid,p_order uuid,p_reference text,p_url text) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.orders set checkout_url=p_url where id=p_order and buyer_id=p_buyer and status='held' and flw_tx_ref=p_reference and checkout_url is null; return found; end $$;
create or replace function public.cancel_checkout(p_buyer uuid,p_order uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare o public.orders%rowtype; begin select * into o from public.orders where id=p_order and buyer_id=p_buyer for update; if not found or o.status<>'held' then return false; end if; update public.orders set status='cancelled' where id=o.id; update public.listings l set status='published',updated_at=now() from public.order_items i where i.order_id=o.id and l.id=i.listing_id and l.status='held'; update public.reservations set status='removed' where order_id=o.id and status='checkout'; return true; end $$;
create or replace function public.expire_orders() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin with expired as (update public.orders set status='expired' where status='held' and hold_until<=now() returning id) update public.listings l set status='published',updated_at=now() from public.order_items i,expired e where i.order_id=e.id and l.id=i.listing_id and l.status='held'; update public.reservations set status='expired' where status='checkout' and expires_at<=now(); get diagnostics n=row_count; return coalesce(n,0); end $$;
create or replace function public.apply_payment_result(p_order uuid,p_tx jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare o public.orders%rowtype; i record; txid text; begin select * into o from public.orders where id=p_order for update; if not found then return jsonb_build_object('ok',false,'reason','not_found'); end if; if o.status='paid' then return jsonb_build_object('ok',true,'duplicate',true); end if; if coalesce(p_tx->>'status','')<>'successful' then return jsonb_build_object('ok',false,'reason','not_successful'); end if; if coalesce(p_tx->>'tx_ref','')<>o.flw_tx_ref or coalesce(p_tx->>'currency','')<>'NGN' or coalesce((p_tx->>'amount')::numeric,0)<>o.amount then return jsonb_build_object('ok',false,'reason','mismatch'); end if; txid:=p_tx->>'id'; if o.status<>'held' or o.hold_until<=now() then update public.orders set status='needs_refund',flw_transaction_id=txid,refund_reason='Payment arrived after the 20-minute hold expired' where id=o.id; return jsonb_build_object('ok',false,'reason','needs_refund'); end if; update public.orders set status='paid',flw_transaction_id=txid,paid_at=now() where id=o.id; update public.listings l set status='sold',updated_at=now() from public.order_items i where i.order_id=o.id and l.id=i.listing_id and l.status='held'; update public.reservations set status='completed' where order_id=o.id and status='checkout'; for i in select * from public.order_items where order_id=o.id loop insert into public.ledger(user_id,direction,amount,entry_type,order_id,reference) values(i.seller_id,'credit',i.net,'sale',o.id,'sale:'||o.id::text||':'||i.listing_id::text) on conflict(reference) do nothing; end loop; return jsonb_build_object('ok',true,'duplicate',false); end $$;
create or replace function public.owner_set_flag(p_owner uuid,p_key text,p_enabled boolean) returns void language plpgsql security definer set search_path=public as $$ declare old boolean; begin if coalesce((select raw_app_meta_data->>'role' from auth.users where id=p_owner),'')<>'owner' then raise exception 'forbidden'; end if; select enabled into old from public.feature_flags where key=p_key for update; if old is null then raise exception 'unknown feature'; end if; update public.feature_flags set enabled=p_enabled,updated_at=now(),updated_by=p_owner where key=p_key; insert into public.feature_flag_logs(key,old_value,new_value,actor_id) values(p_key,old,p_enabled,p_owner); end $$;
create or replace function public.mark_order_refunded(p_owner uuid,p_order uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin if coalesce((select raw_app_meta_data->>'role' from auth.users where id=p_owner),'')<>'owner' then raise exception 'forbidden'; end if; update public.orders set status='refunded',refunded_at=now() where id=p_order and status='needs_refund'; return found; end $$;
create or replace function public.available_balance(p_user uuid) returns bigint language sql stable security definer set search_path=public as $$ select coalesce(sum(case when direction='credit' then amount else -amount end),0)::bigint from public.ledger where user_id=p_user $$;
create or replace function public.create_payout_request(p_user uuid,p_amount bigint,p_reference text,p_resolved_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare p public.profiles%rowtype; id uuid; bal bigint; begin if not coalesce((select enabled from public.feature_flags where key='payouts'),false) then raise exception 'feature disabled'; end if; select * into p from public.profiles where id=p_user; if lower(regexp_replace(coalesce(p.legal_name,''),'[^[:alnum:]]','','g'))<>lower(regexp_replace(coalesce(p_resolved_name,''),'[^[:alnum:]]','','g')) then raise exception 'bank account name does not match profile'; end if; bal:=public.available_balance(p_user); if p_amount<5000 then raise exception 'minimum cash-out is 5000'; end if; if p_amount>bal then raise exception 'amount exceeds available balance'; end if; insert into public.payouts(user_id,amount,reference,status) values(p_user,p_amount,p_reference,'requested') returning id into id; insert into public.ledger(user_id,direction,amount,entry_type,payout_id,reference) values(p_user,'debit',p_amount,'payout',id,'payout:'||p_reference); return id; end $$;
create or replace function public.set_payout_outcome(p_reference text,p_status text,p_provider_id text default null,p_reason text default null) returns void language plpgsql security definer set search_path=public as $$ declare p public.payouts%rowtype; begin select * into p from public.payouts where reference=p_reference for update; if not found then raise exception 'payout missing'; end if; update public.payouts set status=p_status,provider_id=coalesce(p_provider_id,provider_id),reason=p_reason,updated_at=now() where id=p.id; if p_status='failed' then insert into public.ledger(user_id,direction,amount,entry_type,payout_id,reference) values(p.user_id,'credit',p.amount,'payout_reversal',p.id,'payout-reversal:'||p.reference) on conflict(reference) do nothing; end if; end $$;

alter table public.profiles enable row level security;
alter table public.feature_flags enable row level security;
alter table public.feature_flag_logs enable row level security;
alter table public.listings enable row level security;
alter table public.game_art enable row level security;
alter table public.listing_secrets enable row level security;
alter table public.reservations enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.ledger enable row level security;
alter table public.seller_bank_details enable row level security;
alter table public.payouts enable row level security;
alter table public.auth_attempts enable row level security;
create policy profiles_read_self_or_owner on public.profiles for select using(id=auth.uid() or public.is_owner());
drop policy if exists profiles_update_self on public.profiles;
create policy flags_read_public on public.feature_flags for select using(true);
create policy flags_owner_update on public.feature_flags for update using(public.is_owner()) with check(public.is_owner());
create policy logs_owner_read on public.feature_flag_logs for select using(public.is_owner());
create policy listings_public_or_seller on public.listings for select using(status in ('published','reserved') or seller_id=auth.uid() and public.is_admin_or_owner() or public.is_owner());
create policy listings_seller_insert on public.listings for insert with check(seller_id=auth.uid() and public.is_admin_or_owner());
create policy listings_seller_update on public.listings for update using(seller_id=auth.uid() and public.is_admin_or_owner() or public.is_owner()) with check(seller_id=auth.uid() and public.is_admin_or_owner() or public.is_owner());
create policy game_art_public_read on public.game_art for select using(true);
create policy reservation_buyer_read on public.reservations for select using(buyer_id=auth.uid());
create policy order_buyer_or_seller_read on public.orders for select using(public.can_view_order(id));
create policy order_item_buyer_or_seller_read on public.order_items for select using(public.can_view_order(order_id));
create policy ledger_user_or_owner_read on public.ledger for select using(user_id=auth.uid() and public.is_admin_or_owner() or public.is_owner());
create policy bank_user_read_write on public.seller_bank_details for all using(user_id=auth.uid() and public.is_admin_or_owner() or public.is_owner()) with check(user_id=auth.uid() and public.is_admin_or_owner() or public.is_owner());
create policy payout_user_or_owner_read on public.payouts for select using(user_id=auth.uid() and public.is_admin_or_owner() or public.is_owner());
revoke all on public.listing_secrets,public.auth_attempts from anon,authenticated;
revoke insert,update,delete on public.orders,public.order_items,public.ledger,public.payouts,public.feature_flag_logs from anon,authenticated;
grant select on public.listings,public.game_art,public.feature_flags to anon,authenticated;
grant select on public.profiles to authenticated;
grant select on public.reservations,public.orders,public.order_items,public.ledger,public.payouts to authenticated;
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_owner(),public.is_admin_or_owner() to anon,authenticated;
grant execute on function public.can_view_order(uuid) to authenticated;
grant execute on function public.reserve_listing(uuid,uuid),public.release_reservation(uuid,uuid),public.expire_reservations(),public.create_cart_order(uuid,text),public.attach_checkout(uuid,uuid,text,text),public.cancel_checkout(uuid,uuid),public.expire_orders(),public.apply_payment_result(uuid,jsonb),public.owner_set_flag(uuid,text,boolean),public.mark_order_refunded(uuid,uuid),public.available_balance(uuid),public.create_payout_request(uuid,bigint,text,text),public.set_payout_outcome(text,text,text,text),public.consume_auth_attempt(text,integer,integer) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('listing-photos','listing-photos',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy listing_photos_public_read on storage.objects for select using(bucket_id='listing-photos');
create policy listing_photos_owner_insert on storage.objects for insert to authenticated with check(bucket_id='listing-photos' and (public.is_owner() or public.is_admin_or_owner() and (storage.foldername(name))[1]=auth.uid()::text));
create policy listing_photos_seller_delete on storage.objects for delete to authenticated using(bucket_id='listing-photos' and (public.is_owner() or (storage.foldername(name))[1]=auth.uid()::text and public.is_admin_or_owner()));
